const tests = $input.item.json.response;
const inputData = $('Webhook - Code Input').item.json;

// Contar el número de test cases
const testCount = (tests.match(/test\(|it\(/g) || []).length;

// Detectar tipo de tests
const hasUnitTests = tests.toLowerCase().includes('unit test');
const hasIntegrationTests = tests.toLowerCase().includes('integration test');
const hasE2ETests = tests.toLowerCase().includes('e2e') || tests.toLowerCase().includes('end-to-end');

// Extraer imports y mocks
const importsMatch = tests.match(/import[\s\S]+?from[\s\S]+?;/g);
const imports = importsMatch ? importsMatch.join('\n') : '';

const hasMocks = tests.includes('jest.mock') || tests.includes('vi.mock') || tests.includes('sinon');

return {
  json: {
    language: inputData.language,
    testFramework: inputData.testFramework || 'Jest',
    testCode: tests,
    testCount: testCount,
    hasUnitTests: hasUnitTests,
    hasIntegrationTests: hasIntegrationTests,
    hasE2ETests: hasE2ETests,
    hasMocks: hasMocks,
    imports: imports,
    estimatedCoverage: testCount > 10 ? 90 : testCount > 5 ? 75 : 60,
    timestamp: new Date().toISOString()
  }
};
